  {de:"die Zustimmung", pl:"die Zustimmungen", it:"approvazione, consenso", en:"agreement, approval", cat:"varie", ex:[["Kopfschütteln bedeutet in Indien Zustimmung.","In India scuotere la testa significa approvazione."]], enex:[["Kopfschütteln bedeutet in Indien Zustimmung.","In India shaking your head means agreement."]], note:"Verbo: zustimmen (+ Dat). Contrario: die Ablehnung.", enNote:"Verb: zustimmen (+ dat.). Opposite: die Ablehnung."},
  {de:"die Beleidigung", pl:"die Beleidigungen", it:"offesa, insulto", en:"insult", cat:"varie", ex:[["Das kann in anderen Kulturen als Beleidigung verstanden werden.","In altre culture può essere inteso come un'offesa."]], enex:[["Das kann in anderen Kulturen als Beleidigung verstanden werden.","In other cultures that can be taken as an insult."]], note:"Verbo: beleidigen · aggettivo: beleidigt (offeso).", enNote:"Verb: beleidigen · adjective: beleidigt (offended)."},
  {de:"das Rätsel", pl:"die Rätsel", it:"enigma, indovinello", en:"puzzle, riddle", cat:"varie", ex:[["Es ist mir ein Rätsel, wieso er nicht anruft.","Per me è un mistero perché non chiami."]], enex:[["Es ist mir ein Rätsel, wieso er nicht anruft.","It's a mystery to me why he doesn't call."]], note:"Es ist mir ein Rätsel = non riesco proprio a capire (critica gentile).", enNote:"Es ist mir ein Rätsel = I really can't understand it (polite criticism)."},
  {de:"die Rolle", pl:"die Rollen", it:"ruolo", en:"role", cat:"varie", ex:[["Geld spielt eine wichtige Rolle.","I soldi hanno un ruolo importante."]], enex:[["Geld spielt eine wichtige Rolle.","Money plays an important role."]], note:"eine (wichtige) Rolle spielen = essere importante (Nomen-Verb-Verbindung).", enNote:"eine (wichtige) Rolle spielen = to be important (noun-verb combination)."}
